	router.route( axesGridDash() );               // /config/axes/:axis/gridDash
	router.route( axesGridDashOffset() );         // /config/axes/:axis/gridDashOffset
	router.route( axesGridOpacity() );            // /config/axes/:axis/gridOpacity
	router.route( axesGridScale() );              // /config/axes/:axis/gridScale
	router.route( axesGridWidth() );              // /config/axes/:axis/gridWidth
	router.route( axesLabelAlign() );             // /config/axes/:axis/labelAlign
	router.route( axesLabelAngle() );             // /config/axes/:axis/labelAngle
	router.route( axesLabelBaseline() );          // /config/axes/:axis/labelBaseline
	router.route( axesLabelBound() );             // /config/axes/:axis/labelBound
	router.route( axesLabelColor() );             // /config/axes/:axis/labelColor
	router.route( axesLabelFlush() );             // /config/axes/:axis/labelFlush
	router.route( axesLabelFlushOffset() );       // /config/axes/:axis/labelFlushOffset
	router.route( axesLabelFont() );              // /config/axes/:axis/labelFont
	router.route( axesLabelFontSize() );          // /config/axes/:axis/labelFontSize
	router.route( axesLabelFontStyle() );         // /config/axes/:axis/labelFontStyle
	router.route( axesLabelFontWeight() );        // /config/axes/:axis/labelFontWeight
	router.route( axesLabelLimit() );             // /config/axes/:axis/labelLimit
	router.route( axesLabelLineHeight() );        // /config/axes/:axis/labelLineHeight
	router.route( axesLabelOffset() );            // /config/axes/:axis/labelOffset
	router.route( axesLabelOpacity() );           // /config/axes/:axis/labelOpacity
	router.route( axesLabelOverlap() );           // /config/axes/:axis/labelOverlap
	router.route( axesLabelPadding() );           // /config/axes/:axis/labelPadding
	router.route( axesLabels() );                 // /config/axes/:axis/labels
	router.route( axesLabelSeparation() );        // /config/axes/:axis/labelSeparation
	router.route( axesMaxExtent() );              // /config/axes/:axis/maxExtent
	router.route( axesMinExtent() );              // /config/axes/:axis/minExtent
